 'D': lambda p,e,t: p[0]/(1+p[1]*e)*t**3 + p[2]*e/(1+p[3]*e) + p[4]*np.sqrt(t)+p[5]*e**2,
 'E': lambda p,e,t: p[0]/(1+p[1]*e)*t**3 + p[2]*e**1.5/(1+p[3]*e)*np.sqrt(t),
}
for name,fn in forms.items():
    best=None; n=6 if name in 'CD' else 5
