import numpy as np
from scipy.optimize import least_squares
Tf={
 'logT': lambda p,t: p[4]*np.log(t),
 'expT': lambda p,t: p[4]*np.exp(-p[5]*t),
 'invT': lambda p,t: p[4]/t**p[5],
 'T^pow + logT': lambda p,t: p[4]*t**p[5]+p[6]*np.log(t),
 'sqrtT + 1/T': lambda p,t: p[4]*np.sqrt(t)+p[5]/t,
 'T^2 fit': lambda p,t: p[4]*t**2 + p[5]*t,
}
for name,g in Tf.items():
    fn=lambda p,e,t: p[0]/(1+p[1]*e)*t**3 + p[2]*e**p[3]/(1+p[7]*e) + g(p,t)
