            r=least_squares(lambda p: np.nan_to_num(fn(p,eps,T)-sigma,nan=1e6,posinf=1e6), p0)
        except Exception as ex:
            continue
        if best is None or r.cost<best.cost: best=r
    if best is None: print(name,'fail'); continue
    print(name, np.mean(best.fun**2)/np.var(sigma), np.round(best.x,4))
